import{_ as n,a0 as d,w as l,s as p,I as s,x as i,a1 as a,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"4 個用於提高生產力的 Vim 功能 | LCTT x X-CMD","titleTemplate":false,"description":"4 個用於提高生產力的 Vim 功能 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 個用於提高生產力的 Vim 功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 個用於提高生產力的 Vim 功能 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220301 4 Vim features to use to improve productivity","title":"4 個用於提高生產力的 Vim 功能","tag":"202203","desc":""},"relativePath":"202203/20220301 4 Vim features to use to improve productivity.md","filePath":"[post].md"}'),m={name:"202203/20220301 4 Vim features to use to improve productivity.md"};function u(h,e,g,k,c,f){const t=d("Link");return l(),p("div",null,[e[22]||(e[22]=s("h1",{id:"_4-個用於提高生產力的-vim-功能",tabindex:"-1"},[i("4 個用於提高生產力的 Vim 功能 "),s("a",{class:"header-anchor",href:"#_4-個用於提高生產力的-vim-功能","aria-label":"Permalink to “4 個用於提高生產力的 Vim 功能”"},"​")],-1)),e[23]||(e[23]=s("blockquote",null,[s("p",null,"Vim 有很多技巧，即使是用過它很多年的人仍然可以學習新東西。")],-1)),e[24]||(e[24]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202203/04/102118tgy1i7albn6ndiri.jpg",alt:""})],-1)),s("p",null,[e[3]||(e[3]=i("Vim 總在那裏。Vim 是當今最流行的文本編輯器之一。這在很大程度上是因為它隨處可見。當你通過 SSH 連接到另一個系統時，你可能找不到 ",-1)),a(t,{href:"https://opensource.com/article/20/3/getting-started-emacs"},{default:o(()=>[...e[0]||(e[0]=[i("Emacs",-1)])]),_:1}),e[4]||(e[4]=i("、",-1)),a(t,{href:"https://opensource.com/article/20/12/gnu-nano"},{default:o(()=>[...e[1]||(e[1]=[i("Nano",-1)])]),_:1}),e[5]||(e[5]=i(" 或 ",-1)),a(t,{href:"https://opensource.com/article/20/6/open-source-alternatives-vs-code"},{default:o(()=>[...e[2]||(e[2]=[i("VSCodium",-1)])]),_:1}),e[6]||(e[6]=i("，但你可以放心，Vim 就在那裏。",-1))]),e[25]||(e[25]=r('<p>在本文中，我介紹了一些你可以用 Vim 做的中級事情，以加快你的工作流程並通常讓你的一天更輕鬆。本文假設你以前使用過 Vim，已經瞭解編輯器的基礎知識，並希望將你的 Vim 技能提高一個檔次。Vim 充滿了有用的技巧，沒有人真正掌握它，但本文中的五個技巧可以提高你的技能，並希望讓你更加愛上最受歡迎和喜愛的文本編輯器之一。</p><h3 id="vim-書籤" tabindex="-1">Vim 書籤 <a class="header-anchor" href="#vim-書籤" aria-label="Permalink to “Vim 書籤”">​</a></h3><p>Vim 提供了一種在文本中添加書籤的簡單方法。假設你正在編輯一個大文件，並且當前的編輯會話要求你在文件中不同位置的兩段文本之間來回跳轉。</p><p>首先，你輸入 <code>m</code>（用於標記）為當前位置設置一個書籤，然後為其命名。例如，如果我正在編輯的文件中有一個名稱列表，我想稍後再跳回，我可以使用 <code>mn</code>（n 表示名稱）為文件的該部分添加書籤。</p><p>稍後，在編輯文件的另一部分並希望跳回該名稱列表時，我有兩個選項。我可以輸入 `<code>n</code>（反引號 n）轉到書籤的位置，或者我可以鍵入 <code>&#39;n</code>（單引號 n）轉到書籤所在行的開頭。</p><p>當我不再需要書籤時，我可以使用 <code>:delmarks n</code> 將其刪除。<code>:marks</code> 會顯示我所有的書籤。</p><p>請注意，我使用小寫字母來命名我的書籤。這是故意的。你可以使用小寫字母作為本地書籤，使用大寫字母來使書籤在多個文件中具有全局性。</p><h3 id="vim-用户定義的縮寫" tabindex="-1">Vim 用户定義的縮寫 <a class="header-anchor" href="#vim-用户定義的縮寫" aria-label="Permalink to “Vim 用户定義的縮寫”">​</a></h3><p>如果你正在處理的文本有一個長詞或短語多次出現，那麼每次都完整地輸入它會很快變得煩人。幸運的是，Vim 提供了一種創建縮寫的簡單方法。</p><p>要將 <code>Acme Painted Fake Roadways, Inc.</code> 的用户定義縮寫設置為 <code>apfr</code>， 你需要輸入 <code>:ab apfr Acme Painted Fake Roadways, Inc.</code>。現在當在編輯模式時，當你在輸入 <code>apfr</code> 後面更上空格，就會變成 <code>Acme Painted Fake Roadways, Inc.</code>。</p><p>當你關閉 Vim 會話時，你使用 <code>:ab</code> 設置的任何縮寫都會丟失。如果你想在此之前取消設置縮寫，你可輸入 <code>:una apfr</code>。</p><h3 id="vim-自動補全" tabindex="-1">Vim 自動補全 <a class="header-anchor" href="#vim-自動補全" aria-label="Permalink to “Vim 自動補全”">​</a></h3><p>許多人沒有意識到 Vim 帶有自動補全功能。如果你在文件中輸入以前使用過的長詞，這是一個方便的工具。</p><p>假設你正在撰寫一篇文章，多次使用 <code>Antarctica</code> 一詞。使用一次後，下次你可以只輸入前幾個字母。例如，你輸入 <code>Ant</code> 然後按下 <code>Ctrl+P</code>。 Vim 要麼補全單詞（如果只有一個選項），要麼為你提供可以用箭頭鍵選擇的單詞列表，繼續輸入以進一步縮小搜索範圍並使用 <code>Tab</code> 鍵選擇單詞。</p><h3 id="vim-範圍選擇" tabindex="-1">Vim 範圍選擇 <a class="header-anchor" href="#vim-範圍選擇" aria-label="Permalink to “Vim 範圍選擇”">​</a></h3><p>使用 Vim，你可以輕鬆地對文件中的一系列行執行操作。你可以通過起始行號、逗號和結束行號（包括）來指示範圍。除了文字行號之外，你還可以使用句點（<code>.</code>）表示當前行，使用美元符號 （<code>$</code>） 表示文件緩衝區中的最後一行，以及使用百分號（<code>%</code>）表示整個文件。</p><p>這裏舉幾個例子來説明。</p><p>如果要刪除第 2 到 10 行，請輸入（在命令模式下）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:2,10d</span></span></code></pre></div><p>要刪除從第 25 行到文件末尾的每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:25,$d</span></span></code></pre></div><p>你可以使用以下命令刪除每一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:%d</span></span></code></pre></div><p>要將第 5 到 10 行復制（或轉移）到第 15 行之後：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:5,10t 15</span></span></code></pre></div><p>要將第 5 行到第 10 行移動到第 15 行之後（而不是複製）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:5,10m 15</span></span></code></pre></div><h3 id="vim-提高生產力" tabindex="-1">Vim 提高生產力 <a class="header-anchor" href="#vim-提高生產力" aria-label="Permalink to “Vim 提高生產力”">​</a></h3><p>我希望這篇文章教會了你一些關於 Vim 文本編輯器的新知識。 Vim 有很多技巧，即使是使用了多年的人仍然可以學習新事物。總有一些新的和有用的東西可以學習。</p><hr>',30)),s("p",null,[e[8]||(e[8]=i("via: ",-1)),a(t,{href:"https://opensource.com/article/22/3/vim-features-productivity"},{default:o(()=>[...e[7]||(e[7]=[i("https://opensource.com/article/22/3/vim-features-productivity",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=i("作者：",-1)),a(t,{href:"https://opensource.com/users/hunterc"},{default:o(()=>[...e[9]||(e[9]=[i("Hunter Coleman",-1)])]),_:1}),e[14]||(e[14]=i(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[10]||(e[10]=[i("lujun9972",-1)])]),_:1}),e[15]||(e[15]=i(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:o(()=>[...e[11]||(e[11]=[i("geekpi",-1)])]),_:1}),e[16]||(e[16]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[12]||(e[12]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[17]||(e[17]=[i("LCTT",-1)])]),_:1}),e[20]||(e[20]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:o(()=>[...e[18]||(e[18]=[i("Linux中國",-1)])]),_:1}),e[21]||(e[21]=i(" 榮譽推出",-1))])])}const C=n(m,[["render",u]]);export{v as __pageData,C as default};
